import sys
import json
import subprocess
import os

def main(job_file_path):
    with open(job_file_path, 'r') as job_file:
        lines = job_file.readlines()

    command_template = lines[0].strip()
    results = []

    for line in lines[1:]:
        file_path = line.strip()
        if file_path:
            command = command_template.replace('{file}', file_path)
            try:
                result = subprocess.run(command, shell=True, text=True, capture_output=True)
                output = result.stdout + result.stderr
                results.append({
                    'path': file_path,
                    'exit_code': result.returncode,
                    'output': output
                })
            except Exception as e:
                results.append({
                    'path': file_path,
                    'exit_code': 1,
                    'output': str(e)
                })

    print(json.dumps(results, ensure_ascii=False, indent=2))

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python3 batch_run.py <job_file_path>')
        sys.exit(1)
    main(sys.argv[1])
